// TransactionRouting is the resolver for the transactionRouting field.
//
// It returns the routing statuses of the transaction's events for the caller's
// tenants only (request.TenantIDs, the same scope workflowExecutions uses).
func (r *queryResolver) TransactionRouting(ctx context.Context, transactionID uuid.UUID) (*model.TransactionRouting, error) {
	statuses, err := r.workflowRouter.RoutingStatuses(ctx, request.ForContext(ctx).TenantIDs(), transactionID)
	if err != nil {
		return nil, fmt.Errorf("failed to read the routing status of transaction %s: %w", transactionID, err)
	}

	entries := make([]*model.RoutingEntry, 0, len(statuses))
	for _, status := range statuses {
		entries = append(entries, routingEntryModel(status))
	}

	return &model.TransactionRouting{TransactionID: transactionID, Entries: entries}, nil
}
